-- Set abbreviations backfilled from a TCGdex snapshot fetched during research
-- (190 of 205 sets had an official abbreviation; Pocket and most promo sets did not).
ALTER TABLE catalogue_sets ADD COLUMN abbreviation TEXT;
ALTER TABLE catalogue_sets ADD COLUMN abbreviation_source TEXT CHECK (abbreviation_source IS NULL OR abbreviation_source IN ('tcgdex', 'owner'));

